<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_sales_access();$page_title='Sales Pipeline';$current_page='pipeline';$stages=pipeline_stages($pdo);require __DIR__.'/../includes/header.php';
?><div class="pipeline-board"><?php foreach($stages as $st):$params=[(int)$st['id']];$vis=lead_visibility_sql($params,'l');$s=$pdo->prepare("SELECT l.*,u.username assignee FROM leads l LEFT JOIN users u ON u.id=l.assigned_to WHERE l.stage_id=?$vis ORDER BY l.updated_at DESC,l.created_at DESC LIMIT 20");$s->execute($params);$items=$s->fetchAll();?><section class="pipeline-column"><div class="pipeline-column-head"><div><strong><?=e($st['name'])?></strong><small><?=count($items)?> shown</small></div><span class="badge <?=e(stage_class($st['name']))?>"><?=($st['sequence'])?></span></div><?php if(!$items):?><div class="empty">No leads</div><?php else:foreach($items as $l):?><a class="pipeline-card" href="lead.php?id=<?=(int)$l['id']?>"><strong><?=e($l['company']?:($l['name']?:'Unnamed'))?></strong><span><?=e($l['name'])?></span><small><?=e($l['assignee']?:'Unassigned')?> · <?=e($l['priority'])?></small></a><?php endforeach;endif;?></section><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php'; ?>
